const[s,pm,rp,po,ac,fin,reqs,cans,aud,skl]=await Promise.all([api('/admin/stats'),api('/admin/payments'),api('/admin/reports'),api('/admin/commissions'),api('/platform-account'),api('/admin/finance'),api('/admin/requests'),api('/admin/cancellations'),api('/admin/audit'),api('/admin/skills')]);
