const pendP=pm.filter(x=>x.status==='pending').length,openC=po.filter(x=>x.status==='submitted').length,openR=rp.filter(x=>x.status==='open').length,need=pendP+openC+openR;
const stat=(l,v)=>`<div class=stat><small>${l}</small><b>${v}</b></div>`;
const sec=(t,b,n)=>`<section class=panel><div class=sec-h><h3>${t}</h3>${n?`<span class=pill>${n}</span>`:''}</div>${b}</section>`;
const payItem=x=>`<div class=item><div class=row><b>${x.amount} ر.س</b><span class=pill>${PAY[x.status]}</span></div><small>${esc(x.payer)} ← ${esc(x.payee)}، <a href="#/r/${x.request_id}">${esc(x.title)}</a></small><small>من السعر المتفق ${x.agreed_price} ر.س</small><a href=/api/files/${x.proof_id} target=_blank><img class=pic src=/api/files/${x.proof_id} alt="إثبات التحويل"></a>${x.status==='pending'?`<div class=row><button class=btn data-pv=${x.id}>إرفاق إثبات تحويل العميل إلى المساعد</button><button class="btn alt" data-pr=${x.id}>رفض</button></div>`:`<small>${esc(x.note||'')}</small>`}</div>`;
const comItem=x=>`<div class=item><div class=row><b>${x.amount} ر.س</b><span class=pill>${CM[x.status]}</span></div><small>${esc(x.helper)}، <a href="#/r/${x.request_id}">${esc(x.title)}</a></small>${x.proof_id?`<a href=/api/files/${x.proof_id} target=_blank><img class=pic src=/api/files/${x.proof_id} alt="إثبات"></a>`:''}${x.status==='submitted'?`<div class=row><button class=btn data-cv=${x.id}>تأكيد الوصول</button><button class="btn alt" data-cr=${x.id}>رفض</button></div>`:''}</div>`;
const repItem=x=>`<div class=item><div class=row><span class=pill>${({user:'مستخدم',request:'طلب',message:'رسالة',rating:'تقييم'})[x.type]}</span><small>من ${esc(x.reporter)}</small></div><b>${esc(x.info||'')}</b><small>${esc(x.reason)}</small>${x.status==='open'?`<div class=row><button class="btn alt" data-rs=${x.id}>إغلاق</button>${x.type!=='message'?`<button class=btn data-rh=${x.id}>إغلاق مع إخفاء أو تعطيل</button>`:''}</div>`:`<small>مغلق: ${esc(x.note||'')}</small>`}</div>`;
const usrItem=u=>`<div class=item><div class=row><span><b>${esc(u.name)}</b> <small>${esc(u.email)}</small></span><span class=pill>${u.role==='admin'?'مدير':'مستخدم'}</span></div><small dir=ltr>${esc(u.phone||'—')}</small><div class=row><small>إلغاءات 30 يومًا: <b>${u.cancels}</b> · التعهد: ${u.pledged?'موقّع':'غير موقّع'}</small>${u.restricted?'<span class="pill warn">مقيّد</span>':''}</div><div class=row>${u.pledged?`<button class=lnk data-pl=${u.id}>عرض التعهد</button>`:''}<span class=grow></span><button class="btn alt" data-role=${u.id} data-r=${u.role}>تغيير الدور</button><button class="btn alt" data-pw=${u.id}>كلمة المرور</button>${u.restricted?`<button class=btn data-lf=${u.id}>رفع القيود</button>`:''}${u.id===me.user.id?'':`<button class="btn alt" data-u=${u.id} data-a=${u.active}>${u.active?'تعطيل':'تفعيل'}</button>`}</div></div>`;
const money=v=>`${Number(v||0).toLocaleString('ar-SA')} ر.س`;
const fStat=(l,v)=>`<div class=stat><small>${l}</small><b>${v}</b></div>`;
const ledgerHTML=fin.ledger.map(x=>`<div class=row><span><span class=pill>${x.type}</span> ${esc(x.title)}<br><small>${String(x.at||'').slice(0,10)}</small></span><b dir=ltr style="color:${x.type==='وارد'?'var(--g)':'#a3321f'}">${x.type==='وارد'?'+':'−'}${x.amount}</b></div>`).join('')||'<div class=empty>لا توجد حركات بعد.</div>';
const finHTML=`<div class=stats>${fStat('الوارد (عمولات مؤكدة)',money(fin.income))}${fStat('الصادر (مصروفات)',money(fin.expenses))}${fStat('صافي الربح',money(fin.profit))}${fStat('مستحقات بانتظار السداد',money(fin.due))}</div>${sec('إضافة مصروف',`<form id=exf class=form><label>البند<input name=title required minlength=3 maxlength=120></label><label>المبلغ (ر.س)<input name=amount type=number min=0.01 step=0.01 required></label><label>التصنيف<input name=category maxlength=60 placeholder="مثل: استضافة، تسويق، رسوم"></label><button class=btn>تسجيل المصروف</button></form>`)}${sec('سجل الحركات (وارد وصادر)',ledgerHTML)}${sec('ملاحظة',`<small>الوارد هنا هو العمولات المؤكدة فقط. تحويلات المهام بين الطرفين (${money(fin.transfers)} مؤكدة) ليست إيرادًا للمنصة.</small>`)}`;
const viol=s.users_list.filter(u=>u.restricted||u.cancels>0||u.flagged);
const violHTML=`${sec('قانون الجزاءات',`<p class=pre>${esc(ac.penalty_rules||'لم يُكتب بعد. اكتبه من تبويب الإعدادات.')}</p><small>الحدود الحالية: تنبيه عند ${ac.cancel_warn_at} إلغاءات، إيقاف النشر والتقدم عند ${ac.cancel_suspend_at} لمدة ${ac.cancel_suspend_days} أيام، ومراجعة يدوية عند ${ac.cancel_review_at} خلال 30 يومًا.</small>`)}${sec('المستخدمون المخالفون أو المقيدون',viol.map(u=>`<div class=item><div class=row><span><b>${esc(u.name)}</b> <small>${esc(u.email)}</small></span>${u.restricted?'<span class="pill warn">مقيّد</span>':''}</div><small>إلغاءات 30 يومًا: <b>${u.cancels}</b></small><div class=row><button class="btn alt" data-ua=${u.id}>عرض النشاط</button>${u.restricted?`<button class=btn data-lf=${u.id}>رفع القيود</button>`:''}</div></div>`).join('')||'<div class=empty>لا توجد مخالفات حاليًا.</div>')}`;
const reqRows=reqs.map(x=>`<div class=item><div class=row>${stat(x.status)}<small>${String(x.created_at).slice(0,10)}</small></div><b>${esc(x.title)}</b><small>${esc(x.owner)}${x.helper?' ← '+esc(x.helper):''} · ${x.offers} عروض${x.hidden?' · مخفي':''}</small><a href="#/r/${x.id}">فتح الطلب</a></div>`).join('')||'<div class=empty>لا توجد طلبات.</div>';
const cancRows=cans.map(x=>`<div class=item><small>${String(x.created_at).slice(0,16)}</small><span>${esc(x.by_name)} ألغى «${esc(x.title)}»</span><small>السبب: ${esc(x.reason)}</small></div>`).join('')||'<div class=empty>لا توجد إلغاءات.</div>';
const audRows=aud.map(x=>`<div class=item><small>${String(x.at).slice(0,16)} · ${esc(x.admin||'—')}</small><span>${esc(x.action)}</span><small>${esc(x.detail||'')}</small></div>`).join('')||'<div class=empty>لا توجد عمليات.</div>';
const sklRows=skl.map(x=>`<div class=item><div class=row>${x.status==='pending'?'<span class="pill warn">بانتظار الاعتماد</span>':'<span class=pill>معتمدة</span>'}<small>${esc(x.cat)}</small></div><b>${esc(x.name)}</b><small>كلمات: ${esc(x.keywords||'—')}</small>${x.suggested_by?`<small>اقترحها: ${esc(x.suggested_by)}</small>`:''}${x.status==='pending'?`<div class=row><button class=btn data-sk=${x.id} data-d=approve>اعتماد</button><button class="btn alt" data-sk=${x.id} data-d=reject>رفض</button></div>`:`<div class=row><button class="btn alt" data-kw=${x.id}>إضافة كلمات</button></div>`}</div>`).join('')||'<div class=empty>لا توجد مهارات.</div>';
app.innerHTML=`<div class=ahead><div><h2>لوحة الإدارة</h2><small>متابعة المنصة والتحويلات والمستخدمين</small></div></div>
<div class=stats>${stat('المستخدمون',s.users)}${stat('الطلبات',s.requests)}${stat('المكتملة',s.completed)}${stat('الملغاة',s.cancelled)}${stat('نقاط ممنوحة',s.points_issued)}</div>
<nav class=tabs><button class="tab on" data-tab=ops>العمليات ${need?`<i class=cnt>${need}</i>`:''}</button><button class=tab data-tab=finance>المالية</button><button class=tab data-tab=violations>المخالفات</button><button class=tab data-tab=users>المستخدمون</button><button class=tab data-tab=logs>السجلات</button><button class=tab data-tab=settings>الإعدادات</button></nav>
<div class=tabpane data-pane=ops>
${sec('تحويلات الطرفين',pm.map(payItem).join('')||'<div class=empty>لا توجد تحويلات.</div>',pendP)}
${sec('عمولات المنصة',po.map(comItem).join('')||'<div class=empty>لا توجد عمولات.</div>',openC)}
${sec('البلاغات',rp.map(repItem).join('')||'<div class=empty>لا توجد بلاغات.</div>',openR)}
${sec('المهارات المقترحة والمعتمدة',sklRows+'<h4>عمليات بحث لم تجد قسمًا</h4><div id=fsbox></div>',skl.filter(x=>x.status==='pending').length)}
${sec('إعلان للمستخدمين',`<form id=bc class=form><label>نص الإعلان (يصل لكل المستخدمين النشطين)<textarea name=text rows=3 required minlength=5 maxlength=500></textarea></label><button class=btn>إرسال الإعلان</button></form>`)}
${sec('اعتراضات مفتوحة',s.disputes.map(d=>`<a class=row href="#/r/${d.id}">${esc(d.title)}</a>`).join('')||'<div class=empty>لا توجد اعتراضات.</div>')}
</div>
<div class=tabpane data-pane=finance hidden>${finHTML}</div>
<div class=tabpane data-pane=violations hidden>${violHTML}</div>
<div class=tabpane data-pane=users hidden>${sec('المستخدمون',s.users_list.map(usrItem).join('')||'<div class=empty>لا يوجد مستخدمون.</div>')}</div>
<div class=tabpane data-pane=logs hidden><div class=panel style="margin-bottom:10px"><b>رسائل التواصل</b><div id=cmBox></div></div><div class=panel style="margin-bottom:10px"><b>عمولات الاتفاقات المستحقة</b><div id=agcBox></div></div><div class=panel style="margin-bottom:10px"><b>النسخ الاحتياطي</b><br><small>ينزّل نسخة كاملة من قاعدة البيانات. احفظها خارج الاستضافة.</small><br><button class="btn" id=bkBtn type=button style="margin-top:8px">تنزيل نسخة احتياطية</button></div><div class=panel style="margin-bottom:10px"><b>استعادة من نسخة</b><br><small>تحذير: الاستعادة تستبدل كل البيانات الحالية بالنسخة، وتُطبَّق بعد إعادة تشغيل الخادم. يُعمل نسخة أمان قبلها تلقائيًا.</small><br><input type=file id=rsFile accept=".db" style="margin-top:8px"><button class="btn alt" id=rsPrev type=button style="margin-top:8px">معاينة النسخة</button><div id=rsInfo></div></div>${sec('الطلبات (أحدث 100)',reqRows)}${sec('الإلغاءات بعد الاختيار',cancRows)}${sec('سجل العمليات الإدارية',audRows)}${sec('النسخ الاحتياطي',`<p>نسخة كاملة من قاعدة البيانات تُحمّل على جهازك. احفظها في مكان آمن، لأنها تحتوي على بيانات شخصية.</p><a class=btn href="/api/admin/backup">تحميل نسخة احتياطية</a>`)}</div>
<div class=tabpane data-pane=settings hidden>
${sec('حساب المنصة والعمولة',`<form id=as class=form><label>اسم البنك<input name=bank_name value="${esc(ac.bank_name)}"></label><label>اسم الحساب (المؤسسة)<input name=account_name value="${esc(ac.account_name)}"></label><label>الآيبان<input name=iban dir=ltr value="${esc(ac.iban)}" placeholder="SA..."></label><label>نسبة العمولة %<input name=commission_percent type=number min=0 max=100 step=0.1 value="${ac.commission_percent||0}"></label><label>مهلة السداد (أيام)<input name=commission_grace_days type=number min=0 value="${ac.commission_grace_days??3}"></label><label>اسم المؤسسة في التعهد<input name=org_name value="${esc(ac.org_name)}"></label><label>رقم السجل التجاري<input name=org_cr value="${esc(ac.org_cr)}"></label><label>بريد الدعم (يظهر للعموم)<input name=support_email dir=ltr type=email value="${esc(ac.support_email)}"></label><label>رقم الدعم (يظهر للعموم)<input name=support_phone dir=ltr inputmode=tel value="${esc(ac.support_phone)}" placeholder="05XXXXXXXX"></label><label>عنوان المؤسسة (يظهر للعموم)<input name=support_address value="${esc(ac.support_address)}"></label><label>بند الاختصاص والتحكيم<textarea name=dispute_clause rows=3>${esc(ac.dispute_clause)}</textarea></label><label>قانون الجزاءات (يظهر في تبويب المخالفات)<textarea name=penalty_rules rows=6>${esc(ac.penalty_rules)}</textarea></label><label>نص الشروط والأحكام (يظهر في الصفحة العامة، اتركه فارغًا للنص الافتراضي)<textarea name=terms_text rows=8>${esc(ac.terms_text)}</textarea></label><label>نص سياسة الخصوصية (يظهر في الصفحة العامة، اتركه فارغًا للنص الافتراضي)<textarea name=privacy_text rows=8>${esc(ac.privacy_text)}</textarea></label><fieldset><legend>حدود الإلغاء بعد اختيار المساعد (30 يومًا)</legend><label>تنبيه عند<input name=cancel_warn_at type=number min=1 value="${ac.cancel_warn_at}"></label><label>إيقاف النشر والتقدم عند<input name=cancel_suspend_at type=number min=1 value="${ac.cancel_suspend_at}"></label><label>مدة الإيقاف (أيام)<input name=cancel_suspend_days type=number min=1 value="${ac.cancel_suspend_days}"></label><label>مراجعة يدوية عند<input name=cancel_review_at type=number min=1 value="${ac.cancel_review_at}"></label></fieldset><button class=btn>حفظ الإعدادات</button></form>`)}
${sec('نقاط المكافآت',s.rules.map(r=>`<form class="row rule"><span>${RN[r.key]||r.key}</span><input type=hidden name=key value=${r.key}><input name=points type=number min=0 value=${r.points} style="width:110px"><button class=btn>حفظ</button></form>`).join(''))}
</div>`;
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x===b));document.querySelectorAll('.tabpane').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.tab)});
$('#as').onsubmit=sub(async b=>{await api('/admin/settings','POST',b);toast('تم الحفظ')});
$('#exf').onsubmit=sub(async b=>{await api('/admin/expenses','POST',b);toast('تم تسجيل المصروف');admin()});
$('#bc').onsubmit=sub(async b=>{const r=await api('/admin/broadcast','POST',b);toast(`أُرسل الإعلان إلى ${r.sent} مستخدم`);admin()});
document.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{const role=b.dataset.r==='admin'?'user':'admin',reason=prompt(`سبب تغيير الدور إلى ${role==='admin'?'مدير':'مستخدم'}:`);if(!reason)return;try{await api(`/admin/users/${b.dataset.role}/role`,'POST',{role,reason});toast('تم تغيير الدور');admin()}catch(x){toast(x.message,1)}});
document.querySelectorAll('[data-pw]').forEach(b=>b.onclick=async()=>{const password=prompt('كلمة المرور الجديدة (8 أحرف على الأقل):'),reason=password?prompt('سبب إعادة التعيين:'):null;if(!password||!reason)return;try{await api(`/admin/users/${b.dataset.pw}/password`,'POST',{password,reason});toast('تم تغيير كلمة المرور وإنهاء جلساته');admin()}catch(x){toast(x.message,1)}});
document.querySelectorAll('[data-ua]').forEach(b=>b.onclick=async()=>{try{const a=await api(`/admin/users/${b.dataset.ua}/activity`);modal('نشاط المستخدم',`${a.user.name}
الطلبات: ${a.requests}
العروض: ${a.offers}
مهام نفذها: ${a.helped}
مهام مكتملة (له أو منه): ${a.completed}
الإلغاءات: ${a.cancels} (آخر 30 يومًا: ${a.cancels30})
بلاغات ضده: ${a.reports_against}
بلاغات قدّمها: ${a.reports_by}
التقييم: ${a.rating.a??'—'} من ${a.rating.n} تقييم
التعهد: ${a.pledged?'موقّع':'غير موقّع'}
عمولات مستحقة عليه: ${a.commissions_due} ر.س
الحالة: ${a.user.active?'نشط':'معطّل'}${a.user.flagged?'، قيد المراجعة':''}`)}catch(x){toast(x.message,1)}});
document.querySelectorAll('.rule').forEach(f=>f.onsubmit=sub(async b=>{await api('/admin/rules','POST',b);toast('تم الحفظ')}));
const rv=(sel,fn)=>document.querySelectorAll(sel).forEach(b=>b.onclick=async()=>{try{await fn(b);admin()}catch(x){toast(x.message,1)}});
rv('[data-sk]',b=>{const d=b.dataset.d;let reason=null;if(d==='reject'){reason=prompt('سبب الرفض:');if(!reason)throw new Error('السبب مطلوب')}return api(`/admin/skills/${b.dataset.sk}/review`,'POST',{decision:d,reason})});
if($('#bkBtn'))$('#bkBtn').onclick=async()=>{try{const r=await fetch('/api/admin/backup',{credentials:'same-origin'});if(!r.ok)throw new Error('تعذّر تنزيل النسخة');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='backup-'+new Date().toISOString().slice(0,10)+'.db';document.body.append(a);a.click();a.remove();toast('تم تنزيل النسخة الاحتياطية')}catch(x){toast(x.message,1)}};
const rsB64=f=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=()=>rej(new Error('تعذّر قراءة الملف'));r.readAsDataURL(f)});
if($('#rsPrev'))$('#rsPrev').onclick=async()=>{try{const f=$('#rsFile').files[0];if(!f)throw new Error('اختر ملف النسخة أولًا');const d=await api('/admin/restore/preview','POST',{data:await rsB64(f)});$('#rsInfo').innerHTML=`<div class=notice>النسخة تحتوي ${d.counts.users} مستخدمًا و${d.counts.requests} طلبًا و${d.counts.messages} رسالة.</div><input id=rsWord placeholder="اكتب: استعادة" style="margin:6px 0;padding:8px;border:1px solid #d1d5db;border-radius:10px;width:100%"><button class="btn" id=rsGo type=button>تأكيد الاستعادة</button> <button class="btn alt" id=rsNo type=button>إلغاء</button>`;$('#rsGo').onclick=async()=>{try{await api('/admin/restore/apply','POST',{confirm:$('#rsWord').value});$('#rsInfo').innerHTML='<div class=notice>تم تجهيز الاستعادة، وسيُعاد تشغيل الخادم لتطبيقها. أعد تحميل الصفحة بعد دقيقة.</div>'}catch(x){toast(x.message,1)}};$('#rsNo').onclick=async()=>{await api('/admin/restore/cancel','POST');$('#rsInfo').innerHTML=''}}catch(x){toast(x.message,1)}};
api('/admin/agreement-commissions').then(list=>{const b=$('#agcBox');if(!b)return;b.innerHTML=list.map(x=>`<div class=item><b>${x.amount} ريال</b> · ${esc(x.helper)}<br><small>${esc(x.description)}</small><br><button class="btn sm" data-paid="${x.id}">تم السداد</button></div>`).join('')||'<small>لا توجد عمولات مستحقة.</small>';b.querySelectorAll('[data-paid]').forEach(bt=>bt.onclick=async()=>{try{await api('/admin/agreement-commissions/'+bt.dataset.paid+'/paid','POST');toast('تم تسجيل السداد');bt.closest('.item').remove()}catch(x){toast(x.message,1)}})}).catch(()=>{});
api('/admin/contact-messages').then(list=>{const b=$('#cmBox');if(!b)return;b.innerHTML=list.map(x=>`<div class=item><b>${esc(x.name)}</b> · <small dir=ltr>${esc(x.email)}</small><br><small>${esc(String(x.created_at).slice(0,16))}</small><p style="white-space:pre-wrap;margin:6px 0">${esc(x.body)}</p><button class="btn alt sm" data-cmdel="${x.id}">حذف</button></div>`).join('')||'<small>لا توجد رسائل.</small>';b.querySelectorAll('[data-cmdel]').forEach(bt=>bt.onclick=async()=>{try{await api('/admin/contact-messages/'+bt.dataset.cmdel+'/delete','POST');bt.closest('.item').remove()}catch(x){toast(x.message,1)}})}).catch(()=>{});
Promise.all([api('/admin/failed-searches'),api('/skills')]).then(([fs,sk])=>{const b=$('#fsbox');if(!b)return;b.innerHTML=fs.map(x=>`<div class=item><b>${esc(x.text)}</b><small>${x.reason==='no_provider'?'تخصص مطابق ('+esc(x.category||'')+') بلا مساعد'+(x.city?' في '+esc(x.city):''):'لا يوجد تخصص مطابق'} · </small><small>تكرر ${x.n} مرة · آخر مرة ${esc(String(x.last).slice(0,16))}</small><form class=fskw><select name=cat>${sk.categories.map(c=>`<option value=${c.id}>${esc(c.name)}</option>`).join('')}</select><input name=keywords value="${esc(x.text)}"><button class=btn type=submit>أضف للقسم</button></form></div>`).join('')||'<div class=empty>لا توجد عمليات بحث فاشلة.</div>';b.querySelectorAll('.fskw').forEach(f=>f.onsubmit=sub(async d=>{await api('/admin/sections/'+d.cat+'/keywords','POST',{keywords:d.keywords});toast('أُضيفت الكلمات للقسم')}))}).catch(()=>{});
rv('[data-kw]',b=>{const k=prompt('كلمات مفتاحية (افصل بفاصلة):');if(!k)throw new Error('لم تدخل كلمات');return api(`/admin/skills/${b.dataset.kw}/keywords`,'POST',{keywords:k})});
rv('[data-cv]',b=>api(`/admin/commissions/${b.dataset.cv}/review`,'POST',{decision:'verified'}));
rv('[data-cr]',b=>{const note=prompt('سبب الرفض:');if(!note)throw new Error('السبب مطلوب');return api(`/admin/commissions/${b.dataset.cr}/review`,'POST',{decision:'rejected',note})});
rv('[data-pv]',b=>api(`/admin/payments/${b.dataset.pv}/review`,'POST',{decision:'verified'}));
rv('[data-pr]',b=>{const note=prompt('سبب الرفض:');if(!note)throw new Error('السبب مطلوب');return api(`/admin/payments/${b.dataset.pr}/review`,'POST',{decision:'rejected',note})});
const rs=hide=>b=>{const note=prompt('ملاحظة الإغلاق:');if(!note)throw new Error('الملاحظة مطلوبة');return api(`/admin/reports/${b.dataset.rs||b.dataset.rh}/resolve`,'POST',{note,hide})};
