const waIco='<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="#fff" stroke-width="2"><path d="M4 20l1.3-4.1A8 8 0 1 1 8.2 19z"/><path d="M9 9.5c0 2.5 2.5 5 5 5l1-1.2-1.8-1-.8.6c-.9-.4-1.9-1.4-2.3-2.3l.6-.8-1-1.8z" fill="#fff" stroke="none"/></svg>';
const head=`<style>.ct-hero{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 4px 4px}.ct-hero h1{margin:0 0 6px;font-size:30px;color:#0f4f3c}.ct-hero p{margin:0;color:#6b7280;font-size:15px}.ct-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}.ct-card{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:12px;text-decoration:none;color:#111827;box-shadow:0 4px 12px rgba(0,0,0,.04);min-width:0}.ct-ico{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;flex:0 0 auto}.ct-tx{display:flex;flex-direction:column;flex:1;min-width:0}.ct-tx b{font-size:15px}.ct-tx small{color:#6b7280;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ct-ar{font-style:normal;color:#0f6b4f;font-size:22px}.ct-form{background:#fff;border:1px solid #e5e7eb;border-radius:22px;padding:16px;box-shadow:0 6px 18px rgba(0,0,0,.05);display:flex;flex-direction:column;gap:12px}.ct-form h3{margin:0;font-size:18px;color:#111827}.ct-form label{display:flex;flex-direction:column;gap:6px;font-weight:600;color:#111827}.ct-form input,.ct-form textarea{border:1px solid #d1d5db;border-radius:14px;padding:12px;font:inherit;background:#f9fafb}.ct-form textarea{min-height:120px;resize:vertical}.ct-sky{height:90px;margin-top:20px;background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 90' preserveAspectRatio='xMidYMax slice'><g fill='%230f6b4f' opacity='.12'><rect x='20' y='40' width='22' height='50'/><rect x='48' y='22' width='16' height='68'/><path d='M150 90V30l10-14 10 14v60z'/><rect x='180' y='50' width='26' height='40'/><rect x='250' y='10' width='12' height='80'/><circle cx='256' cy='6' r='6'/><rect x='320' y='40' width='24' height='50'/></g></svg>") center bottom/100% auto no-repeat}</style>`;
const hero=`<section class=ct-hero><div><h1>تواصل معنا</h1><p>نحن هنا دائمًا لخدمتكم</p></div><div aria-hidden=true style="font-size:64px;line-height:1">🎧</div></section>`;
const cards=`<div class=ct-cards>${mail?card('mailto:'+mail,mailIco,'البريد الإلكتروني','أرسل لنا رسالة','#0f6b4f'):''}${wa?card(wa,waIco,'واتساب','تواصل معنا مباشرة','#25a85a'):''}</div>`;
